type Subscription = { notify: (progress: number) => void; pending: boolean };
type Generation = {
  live: boolean;
  instance: GsapScrollTriggerInstanceLike | undefined;
  listeners: Set<Subscription>;
  position: number;
  refreshing: boolean;
  revision: number;
};
let current: Generation | undefined;

function retire(generation: Generation): void {
  if (!generation.live) return;
  generation.live = false;
  if (current === generation) current = undefined;
  const instance = generation.instance;
  generation.instance = undefined;
  generation.listeners.clear();
  instance?.kill();
}

function fail(generation: Generation, error: unknown): never {
  try {
    retire(generation);
  } catch (cleanupError) {
    throw new AggregateError([error, cleanupError], "Scroll source failure and cleanup failure.");
  }
  throw error;
}

function snapshot(generation: Generation) {
  try {
    const instance = generation.instance!;
    return { position: instance.scroll(), progress: instance.progress };
  } catch (error) {
    return fail(generation, error);
  }
}

return {
  subscribe(onProgress) {
    const generation = (current ??= {
      live: true, instance: undefined, listeners: new Set<Subscription>(),
      position: 0, refreshing: false, revision: 0,
    });
    const subscription: Subscription = { notify: onProgress, pending: true };
    generation.listeners.add(subscription);

    if (generation.instance === undefined) {
      try {
        generation.instance = scrollTrigger.create({
          trigger: options.trigger, start: options.start, end: options.end,
          pin: options.pin, markers: options.markers ?? false,
          onRefreshInit() {
            if (generation.live && generation.instance !== undefined) generation.refreshing = true;
          },
          onRefresh() {
            if (!generation.live || generation.instance === undefined) return;
            generation.position = snapshot(generation).position;
            generation.refreshing = false;
          },
          onUpdate() {
            // Real GSAP can call back from create(). Ownership is not acquired yet.
            if (!generation.live || generation.instance === undefined || generation.refreshing) return;
            const measured = snapshot(generation);
            if (measured.position === generation.position) return;
            generation.position = measured.position;
            const revision = ++generation.revision;
            const errors: unknown[] = [];
            for (const listener of [...generation.listeners]) {
              if (!generation.live || generation.revision !== revision) break;
              if (!generation.listeners.has(listener)) continue;
              listener.pending = false;
              try { listener.notify(measured.progress); } catch (error) { errors.push(error); }
            }
            if (errors.length === 1) throw errors[0];
            if (errors.length > 1) throw new AggregateError(errors, "Scroll source listener failures.");
          },
        });
        generation.position = snapshot(generation).position;
      } catch (error) {
        return fail(generation, error);
      }
    }

    queueMicrotask(() => {
      if (!generation.live || !generation.listeners.has(subscription) || !subscription.pending) return;
      subscription.pending = false;
      const measured = snapshot(generation);
      subscription.notify(measured.progress);
    });

    return () => {
      subscription.pending = false;
      if (!generation.listeners.delete(subscription)) return;
      if (generation.listeners.size === 0) retire(generation);
    };
  },
};

describe("gsap scroll source producer seam", () => {
  it("shared source refresh holds existing consumers and initializes new ones freshly", async () => {
    const { created, scrollTrigger } = fakeScrollTrigger();
    const source = createGsapScrollSource(scrollTrigger, { trigger: "#scene" });
    const first: number[] = []; const late: number[] = [];
    const detach = source.subscribe(p => { first.push(p); });
    await Promise.resolve();
    created[0]!.emit(0.5); first.length = 0;
    (created[0]!.vars.onRefreshInit as () => void)();
    created[0]!.emit(0.25);
    (created[0]!.vars.onRefresh as () => void)();
    const detachLate = source.subscribe(p => { late.push(p); });
    await Promise.resolve();
    expect(first).toEqual([]); expect(late).toEqual([0.25]);
    detach(); detachLate();
  });

  it("shared source skips a subscription removed earlier in fan-out", async () => {
    const { created, scrollTrigger } = fakeScrollTrigger();
    const source = createGsapScrollSource(scrollTrigger, { trigger: "#scene" });
    const seen: number[] = []; let detachSecond = () => {};
    const detachFirst = source.subscribe(p => { if (p > 0) detachSecond(); });
    detachSecond = source.subscribe(p => { seen.push(p); });
    await Promise.resolve(); seen.length = 0;
    created[0]!.emit(0.6);
    expect(seen).toEqual([]); detachFirst();
  });
